from pathlib import Path
import json
root=Path(__file__).resolve().parent.parent
for b in json.loads((root/'source/brands.json').read_text()):
 css='../../package-css/'+b['id']+'/black-rhino2021/css/'
 styles=''.join('<link rel="stylesheet" href="'+css+n+'"'+(' media="(max-width:960px)"' if n in ['mobile.css','mobileTheme.css'] else ' media="(min-width:961px)"' if n=='theme.css' else '')+'>' for n in ['reset.css','mainStyle.css','mobile.css','theme.css','mobileTheme.css'])
 frames=[['../../cms-assets/'+b['id']+'/carousel-01-670x300.jpg','#','',''],['../../cms-assets/'+b['id']+'/carousel-01-alt-crop-670x300.jpg','#','','']]
 page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self' data:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self' data:; connect-src 'none'; form-action 'none'"><title>'''+b['name']+' · native gallery runtime lane</title>'+styles+'''</head><body><p class="fixtureRuntimeNote">Local native Simple Gallery mouse/runtime lane. Exact existing runtime and package CSS; no eRes/GWT application, keyboard repair, live guest content or transaction.</p><div class="gwt-DialogBox"><div><table><tbody><tr><td class="dialogTopCenter"><div class="dialogTopCenterInner">'''+b['name']+''' · Pictures</div></td></tr><tr><td class="dialogMiddleCenter"><div class="dialogMiddleCenterInner"><div id="main"><div id="gallery"></div></div><div id="formButtons"><button class="gwt-Button" type="button">Close</button></div></div></td></tr></tbody></table></div></div><script src="../runtime/jquery-1.3.2.min.js"></script><script src="../runtime/simplegallery.js"></script><script src="../runtime/create-carousel.js"></script><script>createCarousel('''+json.dumps(frames)+''',"gallery");document.querySelector('#formButtons button').onclick=()=>{document.querySelector('.gwt-DialogBox').style.display='none'};</script></body></html>'''
 (root/'previews'/b['id']/'native-gallery.html').write_text(page,encoding='utf-8')
print('Local native-runtime gallery lane generated; native IMG controls remain unmodified.')
